import{_ as p,a0 as o,w as d,s as r,I as e,x as n,a1 as l,A as i,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何使用 Ansible 安装软件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Ansible 安装软件 | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Ansible 安装软件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Ansible 安装软件 | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200908 How to install software with Ansible","title":"如何使用 Ansible 安装软件","tag":"202010","desc":""},"relativePath":"202010/20200908 How to install software with Ansible.md","filePath":"[post].md"}'),b={name:"202010/20200908 How to install software with Ansible.md"};function c(h,s,g,u,k,m){const a=o("Link");return d(),r("div",null,[s[38]||(s[38]=e("h1",{id:"如何使用-ansible-安装软件",tabindex:"-1"},[n("如何使用 Ansible 安装软件 "),e("a",{class:"header-anchor",href:"#如何使用-ansible-安装软件","aria-label":"Permalink to “如何使用 Ansible 安装软件”"},"​")],-1)),s[39]||(s[39]=e("blockquote",null,[e("p",null,"使用 Ansible 剧本自动安装和更新设备上的软件。")],-1)),s[40]||(s[40]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202010/10/095024hh65atkh6cc8ntn9.jpg",alt:""})],-1)),e("p",null,[s[2]||(s[2]=n("Ansible 是系统管理员和开发人员用来保持计算机系统处于最佳状态的一种流行的自动化工具。与可扩展框架一样，",-1)),l(a,{href:"https://opensource.com/resources/what-ansible"},{default:i(()=>[...s[0]||(s[0]=[n("Ansible",-1)])]),_:1}),s[3]||(s[3]=n(" 本身功能有限，它真正的功能体现在许多模块中。在某种程度上，Ansible 模块就是 ",-1)),l(a,{href:"https://opensource.com/resources/linux"},{default:i(()=>[...s[1]||(s[1]=[n("Linux",-1)])]),_:1}),s[4]||(s[4]=n(" 系统的命令。它们针对特定问题提供解决方案，而维护计算机时的一项常见任务是使所有计算机的更新和一致。",-1))]),s[41]||(s[41]=e("p",null,"我曾经使用软件包的文本列表来保持系统或多或少的同步：我会列出笔记本电脑上安装的软件包，然后将其与台式机或另一台服务器之间进行交叉参考，手动弥补差异。当然，在 Linux 机器上安装和维护应用程序是 Ansible 的一项基本功能，这意味着你可以在自己关心的计算机上列出所需的内容。",-1)),s[42]||(s[42]=e("h3",{id:"寻找正确的-ansible-模块",tabindex:"-1"},[n("寻找正确的 Ansible 模块 "),e("a",{class:"header-anchor",href:"#寻找正确的-ansible-模块","aria-label":"Permalink to “寻找正确的 Ansible 模块”"},"​")],-1)),e("p",null,[s[6]||(s[6]=n("Ansible 模块的数量非常庞大，如何找到能完成你任务的模块？在 Linux 中，你可以在应用程序菜单或 ",-1)),s[7]||(s[7]=e("code",null,"/usr/bin",-1)),s[8]||(s[8]=n(" 中查找要运行的应用程序。使用 Ansible 时，你可以参考 ",-1)),l(a,{href:"https://docs.ansible.com/ansible/latest/modules/modules_by_category.html"},{default:i(()=>[...s[5]||(s[5]=[n("Ansible 模块索引",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),e("p",null,[s[11]||(s[11]=n("这个索引按照类别列出。稍加搜索，你就很可能找到所需的模块。对于包管理，",-1)),l(a,{href:"https://docs.ansible.com/ansible/latest/modules/list_of_packaging_modules.html"},{default:i(()=>[...s[10]||(s[10]=[n("Packaging 模块",-1)])]),_:1}),s[12]||(s[12]=n("几乎适用于所有带包管理器的系统。",-1))]),s[43]||(s[43]=t(`<h3 id="动手写一个-ansible-剧本" tabindex="-1">动手写一个 Ansible 剧本 <a class="header-anchor" href="#动手写一个-ansible-剧本" aria-label="Permalink to “动手写一个 Ansible 剧本”">​</a></h3><p>首先，选择本地计算机上的包管理器。例如，如果你打算在运行 Fedora 的笔记本电脑上编写 Ansible 指令（在 Ansible 中称为“<ruby>剧本<rt>playbook</rt></ruby>”），那么从 <code>dnf</code> 模块开始。如果你在 Elementary OS 上编写，使用 <code>apt</code> 模块，以此类推。这样你就可以开始进行测试和验证，并可以在以后扩展到其它计算机。</p><p>第一步是创建一个代表你的剧本的目录。这不是绝对必要的，但这是一个好习惯。Ansible 只需要一个配置文件就可以运行在 YAML 中，但是如果你以后想要扩展剧本，你就可以通过改变目录和文件的方式来控制 Ansible。现在，只需创建一个名为 <code>install_packages</code> 或类似的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/install_packages</span></span></code></pre></div><p>你可以根据自己的喜好来命名 Ansible 的剧本，但通常将其命名为 <code>site.yml</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch ~/install_packages/site.yml</span></span></code></pre></div><p>在你最喜欢的文本编辑器中打开 <code>site.yml</code>，添加以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - name: install packages</span></span>
<span class="line"><span>      become: true</span></span>
<span class="line"><span>      become_user: root</span></span>
<span class="line"><span>      dnf:</span></span>
<span class="line"><span>        state: present</span></span>
<span class="line"><span>        name:</span></span>
<span class="line"><span>         - tcsh</span></span>
<span class="line"><span>         - htop</span></span></code></pre></div><p>你必须调整使用的模块名称以匹配你使用的发行版。在此示例中，我使用 <code>dnf</code> 是因为我在 Fedora Linux 上编写剧本。</p><p>就像 Linux 终端中的命令一样，知道 <strong>如何</strong> 来调用 Ansible 模块就已经成功了一半。这个示例剧本遵循标准剧本格式：</p><ul><li><code>hosts</code> 是一台或多台计算机。在本示例中，目标计算机是 <code>localhost</code>，即你当前正在使用的计算机（而不是你希望 Ansible 连接的远程系统）。</li><li><code>tasks</code> 是你要在主机上执行的任务列表。 <ul><li><code>name</code> 是任务的人性化名称。在这种情况下，我使用 <code>install packages</code>，因为这就是该任务正在做的事情。</li><li><code>become</code> 允许 Ansible 更改运行此任务的用户。</li><li><code>become_user</code> 允许 Ansible 成为 <code>root</code> 用户来运行此任务。这是必须的，因为只有 root 用户才能使用 <code>dnf</code> 安装应用程序。</li><li><code>dnf</code> 是模块名称，你可以在 Ansible 网站上的模块索引中找到。</li></ul></li></ul><p><code>dnf</code> 下的节点是 <code>dnf</code> 模块专用的。这是模块文档的关键所在。就像 Linux 命令的手册页一样，模块文档会告诉你可用的选项和所需的参数。</p><p><img src="https://opensource.com/sites/default/files/uploads/ansible-module.png" alt="Ansible 文档" title="Ansible documentation"></p><p>安装软件包是一个相对简单的任务，仅需要两个元素。<code>state</code> 选项指示 Ansible 检查系统上是否存在 <strong>软件包</strong>，而 <code>name</code> 选项列出要查找的软件包。Ansible 会针对机器的 <strong>状态</strong> 进行调整，因此模块指令始终意味着更改。假如 Ansible 扫描了系统状态，发现剧本里描述的系统（在本例中，<code>tcsh</code> 和 <code>htop</code> 存在）与实际状态存在冲突，那么 Ansible 的任务是进行必要的更改来使系统与剧本匹配。Ansible 可以通过 <code>dnf</code>（或 <code>apt</code> 或者其它任何包管理器）模块进行更改。</p><p>每个模块可能都有一组不同的选项，所以在编写剧本时，要经常参考模块文档。除非你对模块非常熟悉，否则这是期望模块完成工作的唯一合理方法。</p><h3 id="验证-yaml" tabindex="-1">验证 YAML <a class="header-anchor" href="#验证-yaml" aria-label="Permalink to “验证 YAML”">​</a></h3><p>剧本是用 YAML 编写的。因为 YAML 遵循严格的语法，所以安装 <code>yamllint</code> 来检查剧本是很有帮助的。更妙的是，有一个专门针对 Ansible 的检查工具称为 <code>ansible-lint</code>，它专门为剧本而生。在继续之前，安装它。</p><p>在 Fedora 或 CentOs 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf ins tall yamllint python3-ansible-lint</span></span></code></pre></div><p>在 Debian、Elementary 或 Ubuntu 上，同样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install yamllint ansible-lint</span></span></code></pre></div><p>使用 <code>ansible-link</code> 来验证你的剧本。如果你无法使用 <code>ansible-lint</code>，你可以使用 <code>yamllint</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ansible-lint ~/install_packages/site.yml</span></span></code></pre></div><p>成功则不返回任何内容，但如果文件中有错误，则必须先修复它们，然后再继续。复制和粘贴过程中的常见错误包括在最后一行的末尾省略换行符、使用制表符而不是空格来缩进。在文本编辑器中修复它们，重新运行 <code>ansible-lint</code>，重复这个过程，直到 <code>ansible-lint</code> 或 <code>yamllint</code> 没有返回为止。</p><h3 id="使用-ansible-安装一个应用" tabindex="-1">使用 Ansible 安装一个应用 <a class="header-anchor" href="#使用-ansible-安装一个应用" aria-label="Permalink to “使用 Ansible 安装一个应用”">​</a></h3><p>现在你有了一个可验证的有效剧本，你终于可以在本地计算机上运行它了，因为你碰巧知道该剧本定义的任务需要 root 权限，所以在调用 Ansible 时必须使用 <code>--ask-become-pass</code> 选项，因此系统会提示你输入管理员密码。</p><p>开始安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ansible-playbook --ask-become-pass ~/install_packages/site.yml</span></span>
<span class="line"><span>BECOME password:</span></span>
<span class="line"><span>PLAY [localhost] ******************************</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TASK [Gathering Facts] ******************************</span></span>
<span class="line"><span>ok: [localhost]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TASK [install packages] ******************************</span></span>
<span class="line"><span>ok: [localhost]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PLAY RECAP ******************************</span></span>
<span class="line"><span>localhost: ok=0 changed=2 unreachable=0 failed=0 [...]</span></span></code></pre></div><p>这些命令被执行后，目标系统将处于与剧本中描述的相同的状态。</p><h3 id="在远程系统上安装应用程序" tabindex="-1">在远程系统上安装应用程序 <a class="header-anchor" href="#在远程系统上安装应用程序" aria-label="Permalink to “在远程系统上安装应用程序”">​</a></h3><p>通过这么多操作来替换一个简单的命令可能会适得其反，但是 Ansible 的优势是它可以在你的所有系统中实现自动化。你可以使用条件语句使 Ansible 在不同的系统上使用特定的模块，但是现在，假定所有计算机都使用相同的包管理器。</p><p>要连接到远程系统，你必须在 <code>/etc/ansible/hosts</code> 文件中定义远程系统，该文件与 Ansible 是一起安装的，所以它已经存在了，但它可能是空的，除了一些解释性注释之外。使用 <code>sudo</code> 在你喜欢的文本编辑器中打开它。</p><p>你可以通过其 IP 地址或主机名（只要主机名可以解析）定义主机。例如，如果你已经在 <code>/etc/hosts</code> 中定义了 <code>liavara</code> 并可以成功 <code>ping</code> 通，那么你可以在 <code>/etc/ansible/hosts</code> 中将 <code>liavara</code> 设置为主机。或者，如果你正在运行一个域名服务器或 Avahi 服务器并且可以 <code>ping</code> 通 <code>liavara</code>，那么你就可以在 <code>/etc/ansible/hosts</code> 中定义它。否则，你必须使用它的 IP 地址。</p>`,33)),e("p",null,[s[14]||(s[14]=n("你还必须成功地建立与目标主机的安全 shell（SSH）连接。最简单的方法是使用 ",-1)),s[15]||(s[15]=e("code",null,"ssh-copy-id",-1)),s[16]||(s[16]=n(" 命令，但是如果你以前从未与主机建立 SSH 连接，",-1)),l(a,{href:"https://opensource.com/article/20/8/how-ssh"},{default:i(()=>[...s[13]||(s[13]=[n("阅读我关于如何创建自动 SSH 连接的文章",-1)])]),_:1}),s[17]||(s[17]=n("。",-1))]),s[44]||(s[44]=t(`<p>一旦你在 <code>/etc/ansible/hosts</code> 文件中输入了主机名或 IP 地址后，你就可以在剧本中更改 <code>hosts</code> 定义：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- hosts: all</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - name: install packages</span></span>
<span class="line"><span>      become: true</span></span>
<span class="line"><span>      become_user: root</span></span>
<span class="line"><span>      dnf:</span></span>
<span class="line"><span>        state: present</span></span>
<span class="line"><span>        name:</span></span>
<span class="line"><span>         - tcsh</span></span>
<span class="line"><span>         - htop</span></span></code></pre></div><p>再次运行 <code>ansible-playbook</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ansible-playbook --ask-become-pass ~/install_packages/site.yml</span></span></code></pre></div><p>这次，剧本会在你的远程系统上运行。</p><p>如果你添加更多主机，则有许多方法可以过滤哪个主机执行哪个任务。例如，你可以创建主机组（服务器的 <code>webserves</code>，台式机的 <code>workstations</code>等）。</p><h3 id="适用于混合环境的-ansible" tabindex="-1">适用于混合环境的 Ansible <a class="header-anchor" href="#适用于混合环境的-ansible" aria-label="Permalink to “适用于混合环境的 Ansible”">​</a></h3><p>到目前为止，我们一直假定 Ansible 配置的所有主机都运行相同的操作系统（都是是使用 <code>dnf</code> 命令进行程序包管理的操作系统）。那么，如果你要管理不同发行版的主机，例如 Ubuntu（使用 <code>apt</code>）或 Arch（使用 <code>pacman</code>），或者其它的操作系统时，该怎么办？</p>`,8)),e("p",null,[s[20]||(s[20]=n("只要目标操作系统具有程序包管理器（",-1)),l(a,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:i(()=>[...s[18]||(s[18]=[n("MacOs 有 Homebrew",-1)])]),_:1}),s[21]||(s[21]=n("，",-1)),l(a,{href:"https://opensource.com/article/20/3/chocolatey"},{default:i(()=>[...s[19]||(s[19]=[n("Windows 有 Chocolatey",-1)])]),_:1}),s[22]||(s[22]=n("），Ansible 就能派上用场。",-1))]),s[45]||(s[45]=t(`<p>这就是 Ansible 优势最明显的地方。在 shell 脚本中，你必须检查目标主机上有哪些可用的包管理器，即使使用纯 Python，也必须检查操作系统。Ansible 不仅内置了这些功能，而且还具有在剧本中使用命令结果的机制。你可以使用 <code>action</code> 关键字来执行由 Ansible 事实收集子系统提供的变量定义的任务，而不是使用 <code>dnf</code> 模块。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- hosts: all</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - name: install packages</span></span>
<span class="line"><span>      become: true</span></span>
<span class="line"><span>      become_user: root</span></span>
<span class="line"><span>      action: &gt;</span></span>
<span class="line"><span>       {{ ansible_pkg_mgr }} name=htop,transmission state=present update_cache=yes</span></span></code></pre></div><p><code>action</code> 关键字会加载目标插件。在本例中，它使用了 <code>ansible_pkg_mgr</code> 变量，该变量由 Ansible 在初始 <strong>收集信息</strong> 期间填充。你不需要告诉 Ansible 收集有关其运行操作系统的事实，所以很容易忽略这一点，但是当你运行一个剧本时，你会在默认输出中看到它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TASK [Gathering Facts] *****************************************</span></span>
<span class="line"><span>ok: [localhost]</span></span></code></pre></div><p><code>action</code> 插件使用来自这个探针的信息，使用相关的包管理器命令填充 <code>ansible_pkg_mgr</code>，以安装在 <code>name</code> 参数之后列出的程序包。使用 8 行代码，你可以克服在其它脚本选项中很少允许的复杂跨平台难题。</p><h3 id="使用-ansible" tabindex="-1">使用 Ansible <a class="header-anchor" href="#使用-ansible" aria-label="Permalink to “使用 Ansible”">​</a></h3><p>现在是 21 世纪，我们都希望我们的计算机设备能够互联并且相对一致。无论你维护的是两台还是 200 台计算机，你都不必一次又一次地执行相同的维护任务。使用 Ansible 来同步生活中的计算机设备，看看 Ansible 还能为你做些什么。</p><hr>`,8)),e("p",null,[s[24]||(s[24]=n("via: ",-1)),l(a,{href:"https://opensource.com/article/20/9/install-packages-ansible"},{default:i(()=>[...s[23]||(s[23]=[n("https://opensource.com/article/20/9/install-packages-ansible",-1)])]),_:1})]),e("p",null,[s[29]||(s[29]=n("作者：",-1)),l(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[25]||(s[25]=[n("Seth Kenlon",-1)])]),_:1}),s[30]||(s[30]=n(" 选题：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[26]||(s[26]=[n("lujun9972",-1)])]),_:1}),s[31]||(s[31]=n(" 译者：",-1)),l(a,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[27]||(s[27]=[n("MjSeven",-1)])]),_:1}),s[32]||(s[32]=n(" 校对：",-1)),l(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[28]||(s[28]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=n("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[33]||(s[33]=[n("LCTT",-1)])]),_:1}),s[36]||(s[36]=n(" 原创编译，",-1)),l(a,{href:"https://linux.cn/"},{default:i(()=>[...s[34]||(s[34]=[n("Linux中国",-1)])]),_:1}),s[37]||(s[37]=n(" 荣誉推出",-1))])])}const C=p(b,[["render",c]]);export{y as __pageData,C as default};
